using System.Diagnostics;
using LiteNetLib.Utils;
using Zuzel;
var report=new List<string>();void Check(bool value,string label){if(!value)throw new Exception(label);report.Add("PASS "+label);Console.WriteLine(report[^1]);}
try{
if(args.Length>=2&&args[0]=="--live-five"){
    var live=Enumerable.Range(0,5).Select(i=>new OnlineClient(args[1],9050,"Kontrola "+i,CompetitionMode.Individual)).ToArray();try{var clock=Stopwatch.StartNew();while(clock.Elapsed.TotalSeconds<15&&live.Any(c=>c.Latest==null)){foreach(var c in live)c.Poll();Thread.Sleep(5);}Check(live.All(c=>c.Latest!=null),"Five clients connect to the public server");Check(live.GroupBy(c=>c.Latest!.Room).Select(g=>g.Count()).OrderBy(n=>n).SequenceEqual(new[]{1,4}),"Public server splits five connections into a full room and a second room");foreach(var c in live)Console.WriteLine($"room={c.Latest!.Room} slot={c.Latest.Slot+1} ping={c.Ping}");return 0;}finally{foreach(var c in live)c.Dispose();}
}
if(args.Length>=2&&args[0]=="--probe"){
    using var client=new OnlineClient(args[1],9050,"Kontrola",CompetitionMode.Individual);var clock=Stopwatch.StartNew();while(client.Latest==null&&!client.Failed&&clock.Elapsed.TotalSeconds<15){client.Poll();Thread.Sleep(5);}Check(client.Latest!=null,"Live server accepts UDP connection and assigns a room");Console.WriteLine($"room={client.Latest!.Room} slot={client.Latest.Slot+1} phase={client.Latest.Phase}");return 0;
}
var directory=new RoomDirectory(3);Check(directory.Rooms.Count==1&&directory.Rooms[0].Number==1,"Server starts with exactly room 1");for(int i=0;i<4;i++){var seat=directory.Join(i.ToString(),"Test "+i,CompetitionMode.Individual);Check(seat?.Room.Number==1&&seat.Value.Slot==i,"First four players join room 1");}var fifth=directory.Join("4","Fifth",CompetitionMode.Individual);Check(fifth?.Room.Number==2&&directory.Rooms.Count==2,"Fifth player automatically opens room 2");Check(directory.Rooms.All(r=>r.Count<=4),"A room never has more than four players");
directory.Leave("1");Check(directory.Join("replacement","Replacement",CompetitionMode.Individual)?.Room.Number==1,"Vacant waiting-room seat is reused before creating rooms");var first=directory.Rooms[0];foreach(var s in first.Seats.Select((s,i)=>(s,i)))first.SetReady(s.i,true,first.Epoch);directory.Step(1f/120,0);Check(first.Phase==RoomPhase.Countdown&&first.Locked,"All ready players lock the room and begin countdown");directory.Leave("0");Check(directory.Join("new","New",CompetitionMode.Individual)?.Room.Number==2,"New users cannot replace competitors in an active tournament");
Check(first.SetInput(1,10,new(1,-1),1)&&!first.SetInput(1,9,new(1,1),1),"Stale input sequences are rejected");Check(!first.SetInput(1,11,new(float.NaN,0),1),"Non-finite input is rejected");
var snapshot=first.Snapshot(1);var bytes=Wire.Encode(snapshot).CopyData();Check(bytes.Length<1000,"Full room snapshot fits comfortably within a UDP packet");var reader=new NetDataReader(bytes);Check(reader.GetByte()==Wire.State,"Snapshot has a protocol marker");var decoded=Wire.Decode(reader);Check(decoded.Room==1&&decoded.Names[1]==snapshot.Names[1]&&decoded.Riders.Length==4,"Binary protocol roundtrip preserves room and rider data");
var fifteen=new OnlineRoom(100,CompetitionMode.Team);fifteen.Join("human","Fifteen heats",CompetitionMode.Team);fifteen.SetReady(0,true,fifteen.Epoch);double simulation=0;uint inputSequence=0;for(int n=0;n<120*1500&&fifteen.Phase!=RoomPhase.Finished;n++){simulation+=1d/120;if(fifteen.Phase==RoomPhase.Results)fifteen.SetReady(0,true,fifteen.Epoch);fifteen.SetInput(0,++inputSequence,fifteen.Phase==RoomPhase.Racing?fifteen.Race.AI(fifteen.Race.Riders[0]):default,simulation);fifteen.Step(1f/120,simulation);}Check(fifteen.Phase==RoomPhase.Finished&&fifteen.Tournament.History.Count==15&&fifteen.Tournament.Points.Sum()==90,"Online room completes fifteen heats and sums all ninety points");fifteen.SetReady(0,true,fifteen.Epoch);fifteen.Step(1f/120,simulation);Check(fifteen.Phase==RoomPhase.Lobby&&fifteen.Tournament.Points.Sum()==0,"After the final results the room returns to a clean lobby");
var team=directory.Join("team","Team",CompetitionMode.Team);Check(team?.Room.Number==3&&team.Value.Room.Mode==CompetitionMode.Team,"Individual and team players get compatible rooms");Check(directory.Join("overflow","Extra",CompetitionMode.Team)!=null,"Existing room accepts a compatible player at server room limit");
var solo=new OnlineRoom(99,CompetitionMode.Individual);int soloSlot=solo.Join("solo","Solo",CompetitionMode.Individual);solo.SetReady(soloSlot,true,solo.Epoch);double now=0;solo.Step(1f/120,now);for(int n=0;n<500;n++){now+=1d/120;solo.Step(1f/120,now);}Check(solo.Phase==RoomPhase.Racing,"Ready solo player can race with three AI riders");for(int n=0;n<120*160;n++){now+=1d/120;solo.Step(1f/120,now);if(solo.Phase==RoomPhase.Results)break;}Check(solo.Phase==RoomPhase.Results&&solo.Tournament.History.Count==1,"Stalled racer times out and room progresses to the next heat");solo.Leave("solo");Check(solo.Phase==RoomPhase.Lobby&&!solo.Locked,"Empty active room resets to an available lobby");
using(var server=new GameServer(0)){
    var clients=Enumerable.Range(0,5).Select(i=>new OnlineClient("127.0.0.1",server.Port,"UDP "+i,CompetitionMode.Individual)).ToArray();try{
        var watch=Stopwatch.StartNew();while(watch.Elapsed.TotalSeconds<8&&clients.Any(c=>c.Latest==null)){server.Poll();server.Step(1f/120);foreach(var c in clients)c.Poll();Thread.Sleep(5);}Check(clients.All(c=>c.Latest!=null),"Five actual UDP clients all receive server snapshots");Check(clients.GroupBy(c=>c.Latest!.Room).Select(g=>g.Count()).OrderBy(n=>n).SequenceEqual(new[]{1,4}),"Actual network clients are split four plus one across two rooms");
        var racingClients=clients.GroupBy(c=>c.Latest!.Room).OrderByDescending(g=>g.Count()).First().ToArray();var waitingClient=clients.Except(racingClients).Single();foreach(var c in racingClients)c.Ready();watch.Restart();while(watch.Elapsed.TotalSeconds<7&&racingClients.Any(c=>c.Latest!.Phase!=RoomPhase.Racing)){server.Poll();server.Step(1f/120);foreach(var c in clients)c.Poll();Thread.Sleep(7);}Check(racingClients.All(c=>c.Latest!.Phase==RoomPhase.Racing),"Four ready network clients enter the same live race");
        var racer=racingClients[0];float oldX=racer.Latest!.Riders[racer.Latest.Slot].X;watch.Restart();while(watch.Elapsed.TotalSeconds<1){server.Poll();racer.SendInput(new(1,0));server.Step(1f/120);foreach(var c in clients)c.Poll();Thread.Sleep(8);}Check(racer.Latest!.Riders[racer.Latest.Slot].X<oldX-5,"Remote throttle input moves the server-authoritative motorcycle");Check(waitingClient.Latest!.Phase==RoomPhase.Lobby,"Second room stays independent while room 1 races");
    }finally{foreach(var c in clients)c.Dispose();}
}
File.WriteAllLines("online-tests.txt",report);Console.WriteLine("ALL ONLINE TESTS PASSED");return 0;
}catch(Exception e){Console.Error.WriteLine(e);report.Add("FAIL "+e);File.WriteAllLines("online-tests.txt",report);return 1;}
